-- Rôle de chaque semaine dans le plan (translations_json.weeks, 9 langues). Rejouable.
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Adaptation : blocs TT de 15 à 20'' en endurance, tempo court et une sortie longue de 90''. On installe la position à basse intensité avant d''empiler les heures.", "en": "Adaptation: 15 to 20'' TT blocks at endurance pace, short tempo and a 90'' long ride. We settle the position at low intensity before piling on the hours.", "es": "Adaptación: bloques de 15 a 20'' en TT en resistencia, tempo corto y una salida larga de 90''. Asentamos la posición a baja intensidad antes de acumular horas.", "it": "Adattamento: blocchi in TT da 15 a 20'' in endurance, ritmo tempo breve e un''uscita lunga di 90''. Fissiamo la posizione a bassa intensità prima di accumulare ore.", "pt": "Adaptação: blocos em TT de 15 a 20'' em endurance, ritmo tempo curto e um treino longo de 90''. Fixamos a posição em baixa intensidade antes de acumular horas.", "de": "Anpassung: TT-Blöcke von 15 bis 20'' im Grundlagenbereich, kurzes Tempo und eine lange Fahrt von 90''. Wir festigen die Position bei niedriger Intensität, bevor die Stunden zunehmen.", "nl": "Aanpassing: TT-blokken van 15 tot 20'' in duurtempo, kort tempo en een lange rit van 90''. We leren de houding aan op lage intensiteit voordat de uren zich opstapelen.", "ja": "適応：エンデュランスで15〜20''のTTブロック、短いテンポ、90''のロングライド。時間を積み上げる前に、低強度でポジションを定着させます。", "tr": "Uyum: dayanıklılık temposunda 15-20''lik TT blokları, kısa tempo ve 90'' uzun sürüş. Saatleri üst üste koymadan önce pozisyonu düşük yoğunlukta oturtuyoruz."}, "2": {"fr": "Les blocs s''allongent de 5'' et la sortie longue passe à près de 2 h. La progression est volontairement lente : ce sont les tissus du cou et du dos qui fixent le rythme, pas le cardio.", "en": "Blocks get 5'' longer and the long ride goes up to nearly 2 h. Progress is deliberately slow: your neck and back tissues set the pace, not your cardio.", "es": "Los bloques se alargan 5'' y la salida larga pasa a casi 2 h. La progresión es lenta a propósito: son los tejidos del cuello y la espalda los que marcan el ritmo, no el cardio.", "it": "I blocchi si allungano di 5'' e l''uscita lunga arriva a quasi 2 h. La progressione è volutamente lenta: sono i tessuti di collo e schiena a dettare il ritmo, non il cuore.", "pt": "Os blocos ganham 5'' e o treino longo passa para quase 2 h. A progressão é propositalmente lenta: são os tecidos do pescoço e das costas que ditam o ritmo, não o cardio.", "de": "Die Blöcke werden 5'' länger und die lange Fahrt geht auf fast 2 h. Der Aufbau ist bewusst langsam: Das Gewebe von Nacken und Rücken bestimmt das Tempo, nicht das Herz-Kreislauf-System.", "nl": "De blokken worden 5'' langer en de lange rit gaat naar bijna 2 u. De opbouw is bewust traag: de weefsels van nek en rug bepalen het ritme, niet je conditie.", "ja": "ブロックが5''伸び、ロングライドは2時間近くに。進み方はあえてゆっくり：ペースを決めるのは心肺ではなく首と背中の組織です。", "tr": "Bloklar 5'' uzuyor ve uzun sürüş 2 saate yaklaşıyor. İlerleme bilerek yavaş: ritmi kalp değil, boyun ve sırt dokuları belirliyor."}, "3": {"fr": "Fin du premier cycle et semaine la plus lourde : 2×30'' en TT, tempo 3×15'' et 2 h 15 de sortie longue. Cette surcharge prépare le saut du deuxième cycle.", "en": "End of the first cycle and the heaviest week: 2×30'' in TT, tempo 3×15'' and a 2 h 15 long ride. This overload prepares the jump into the second cycle.", "es": "Fin del primer ciclo y semana más pesada: 2×30'' en TT, tempo 3×15'' y 2 h 15 de salida larga. Esta sobrecarga prepara el salto del segundo ciclo.", "it": "Fine del primo ciclo e settimana più pesante: 2×30'' in TT, ritmo tempo 3×15'' e 2 h 15 di uscita lunga. Questo sovraccarico prepara il salto del secondo ciclo.", "pt": "Fim do primeiro ciclo e semana mais pesada: 2×30'' em TT, ritmo tempo 3×15'' e 2 h 15 de treino longo. Essa sobrecarga prepara o salto do segundo ciclo.", "de": "Ende des ersten Zyklus und härteste Woche: 2×30'' in TT, Tempo 3×15'' und 2 h 15 lange Fahrt. Diese Belastungsspitze bereitet den Sprung im zweiten Zyklus vor.", "nl": "Einde van de eerste cyclus en zwaarste week: 2×30'' in TT, tempo 3×15'' en een lange rit van 2 u 15. Deze piekbelasting bereidt de sprong van de tweede cyclus voor.", "ja": "第1サイクルの終わりで最も重い週：TTで2×30''、テンポ3×15''、2時間15分のロングライド。このオーバーロードが第2サイクルへの飛躍を準備します。", "tr": "İlk döngünün sonu ve en ağır hafta: TT''de 2×30'', tempo 3×15'' ve 2 sa 15 uzun sürüş. Bu yüklenme ikinci döngüdeki sıçramayı hazırlıyor."}, "4": {"fr": "On souffle avant le 2e cycle : blocs ramenés à 20'', une séance en moins. Les 45'' d''affilée de la semaine 5 seront plus faciles si tu arrives frais.", "en": "A breather before the 2nd cycle: blocks back to 20'', one session fewer. Week 5''s 45'' straight will be easier if you arrive fresh.", "es": "Respiramos antes del 2.º ciclo: bloques reducidos a 20'', una sesión menos. Los 45'' seguidos de la semana 5 serán más fáciles si llegas fresco.", "it": "Si tira il fiato prima del 2° ciclo: blocchi riportati a 20'', una seduta in meno. I 45'' di fila della settimana 5 saranno più facili se arrivi fresco.", "pt": "Respiramos antes do 2º ciclo: blocos de volta a 20'', uma sessão a menos. Os 45'' seguidos da semana 5 serão mais fáceis se você chegar descansado.", "de": "Durchatmen vor dem 2. Zyklus: Blöcke zurück auf 20'', eine Einheit weniger. Die 45'' am Stück in Woche 5 fallen leichter, wenn du frisch ankommst.", "nl": "Op adem komen voor de 2e cyclus: blokken terug naar 20'', één training minder. De 45'' aan één stuk van week 5 gaan makkelijker als je fris aan de start komt.", "ja": "第2サイクルの前にひと息：ブロックは20''に戻し、セッションを1回減らします。フレッシュな状態で臨めば、5週目の45''連続が楽になります。", "tr": "2. döngüden önce nefes al: bloklar 20'' oluyor, bir antrenman eksik. Taze gelirsen 5. haftadaki kesintisiz 45'' daha kolay olur."}, "5": {"fr": "Début du deuxième cycle : les blocs ne sont plus fractionnés, 45'' d''affilée en TT. On passe de « tenir des blocs » à « tenir une durée », ce qu''exige une course longue.", "en": "Start of the second cycle: blocks are no longer split, 45'' straight in TT. We move from “holding blocks” to “holding a duration”, which is what a long race demands.", "es": "Inicio del segundo ciclo: los bloques ya no se fraccionan, 45'' seguidos en TT. Pasamos de «aguantar bloques» a «aguantar una duración», lo que exige una carrera larga.", "it": "Inizio del secondo ciclo: i blocchi non sono più frazionati, 45'' di fila in TT. Si passa da «reggere dei blocchi» a «reggere una durata», ciò che richiede una gara lunga.", "pt": "Início do segundo ciclo: os blocos não são mais fracionados, 45'' seguidos em TT. Passamos de “segurar blocos” para “segurar uma duração”, o que uma prova longa exige.", "de": "Beginn des zweiten Zyklus: Die Blöcke sind nicht mehr unterteilt, 45'' am Stück in TT. Wir gehen von „Blöcke halten“ zu „eine Dauer halten“ über – das, was ein langes Rennen verlangt.", "nl": "Begin van de tweede cyclus: de blokken zijn niet meer opgedeeld, 45'' aan één stuk in TT. We gaan van ‘blokken volhouden’ naar ‘een duur volhouden’, wat een lange wedstrijd vraagt.", "ja": "第2サイクルの開始：ブロックはもう分割せず、TTで45''連続。「ブロックを保つ」から「時間を保つ」へ、長いレースが求めるものです。", "tr": "İkinci döngünün başı: bloklar artık bölünmüyor, TT''de kesintisiz 45''. «Blok tutmaktan» «süre tutmaya» geçiyoruz, uzun bir yarışın istediği bu."}, "6": {"fr": "Une heure d''affilée en TT et le tempo en 2×25''. C''est la semaine où la position devient une habitude plutôt qu''un effort ; surveille la tête, c''est elle qui lâche en premier.", "en": "One hour straight in TT and tempo as 2×25''. This is the week the position becomes a habit rather than an effort; watch your head, it''s the first thing to give way.", "es": "Una hora seguida en TT y el tempo en 2×25''. Es la semana en que la posición se convierte en hábito más que en esfuerzo; vigila la cabeza, es lo primero que cede.", "it": "Un''ora di fila in TT e il ritmo tempo in 2×25''. È la settimana in cui la posizione diventa un''abitudine più che uno sforzo; controlla la testa, è lei che cede per prima.", "pt": "Uma hora seguida em TT e o ritmo tempo em 2×25''. É a semana em que a posição vira hábito em vez de esforço; fique de olho na cabeça, é ela que cede primeiro.", "de": "Eine Stunde am Stück in TT und Tempo in 2×25''. In dieser Woche wird die Position eher zur Gewohnheit als zur Anstrengung; achte auf den Kopf, er gibt als Erstes nach.", "nl": "Een uur aan één stuk in TT en tempo in 2×25''. Deze week wordt de houding eerder een gewoonte dan een inspanning; let op je hoofd, dat geeft als eerste op.", "ja": "TTで1時間連続、テンポは2×25''。ポジションが努力ではなく習慣になる週です。頭に注意、最初に崩れるのは頭です。", "tr": "TT''de kesintisiz bir saat ve tempo 2×25''. Pozisyonun bir efor değil alışkanlık olduğu hafta; başına dikkat et, ilk o bırakır."}, "7": {"fr": "Le pic du plan : 75'' d''affilée, 2×45'' et 2 h 35 de sortie longue. Tout ce qui suit ne sert qu''à récupérer et confirmer ce niveau.", "en": "The peak of the plan: 75'' straight, 2×45'' and a 2 h 35 long ride. Everything after this is only for recovering and confirming this level.", "es": "El pico del plan: 75'' seguidos, 2×45'' y 2 h 35 de salida larga. Todo lo que sigue solo sirve para recuperar y confirmar este nivel.", "it": "Il picco del piano: 75'' di fila, 2×45'' e 2 h 35 di uscita lunga. Tutto ciò che segue serve solo a recuperare e confermare questo livello.", "pt": "O pico do plano: 75'' seguidos, 2×45'' e 2 h 35 de treino longo. Tudo o que vem depois serve só para recuperar e confirmar esse nível.", "de": "Der Höhepunkt des Plans: 75'' am Stück, 2×45'' und 2 h 35 lange Fahrt. Alles, was folgt, dient nur noch der Erholung und der Bestätigung dieses Niveaus.", "nl": "Het hoogtepunt van het plan: 75'' aan één stuk, 2×45'' en een lange rit van 2 u 35. Alles wat volgt dient alleen nog om te herstellen en dit niveau te bevestigen.", "ja": "プランのピーク：75''連続、2×45''、2時間35分のロングライド。この後はすべて回復とこのレベルの確認のためです。", "tr": "Planın zirvesi: kesintisiz 75'', 2×45'' ve 2 sa 35 uzun sürüş. Bundan sonrası sadece toparlanmak ve bu seviyeyi teyit etmek için."}, "8": {"fr": "Semaine allégée et test : 90'' d''affilée en TT lors de la sortie longue. La charge baisse pour que tu arrives frais sur ce dernier passage, qui valide l''objectif du plan.", "en": "Lighter week and test: 90'' straight in TT during the long ride. The load drops so you arrive fresh for this final effort, which validates the plan''s goal.", "es": "Semana más ligera y test: 90'' seguidos en TT durante la salida larga. La carga baja para que llegues fresco a este último tramo, que valida el objetivo del plan.", "it": "Settimana di scarico e test: 90'' di fila in TT durante l''uscita lunga. Il carico cala perché tu arrivi fresco a quest''ultimo passaggio, che convalida l''obiettivo del piano.", "pt": "Semana mais leve e teste: 90'' seguidos em TT durante o treino longo. A carga diminui para você chegar descansado a esta última passagem, que valida o objetivo do plano.", "de": "Entlastungswoche und Test: 90'' am Stück in TT während der langen Fahrt. Die Belastung sinkt, damit du frisch in diesen letzten Abschnitt gehst, der das Ziel des Plans bestätigt.", "nl": "Lichtere week en test: 90'' aan één stuk in TT tijdens de lange rit. De belasting daalt zodat je fris aan deze laatste passage begint, die het doel van het plan bevestigt.", "ja": "軽めの週とテスト：ロングライドでTT 90''連続。負荷を下げ、プランの目標を検証するこの最後の走行にフレッシュな状態で臨みます。", "tr": "Hafif hafta ve test: uzun sürüşte TT''de kesintisiz 90''. Planın hedefini doğrulayan bu son geçişe taze gelmen için yük azalıyor."}}'::jsonb) WHERE name_key = 'endurance_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Découverte : sprints assis de 15'''', relances d''1'' et premiers 30/30, tous en TT. On apprend le geste explosif en position avant de chercher la puissance.", "en": "Discovery: seated 15'''' sprints, one-minute surges and first 30/30s, all in TT. We learn the explosive movement in position before chasing power.", "es": "Descubrimiento: sprints sentado de 15'''', cambios de ritmo de 1'' y primeros 30/30, todo en TT. Aprendemos el gesto explosivo en posición antes de buscar la potencia.", "it": "Scoperta: sprint da seduto di 15'''', rilanci di 1'' e primi 30/30, tutti in TT. Si impara il gesto esplosivo in posizione prima di cercare la potenza.", "pt": "Descoberta: sprints sentado de 15'''', retomadas de 1'' e primeiros 30/30, todos em TT. Aprendemos o gesto explosivo na posição antes de buscar potência.", "de": "Kennenlernen: Sitzsprints à 15'''', Antritte à 1'' und erste 30/30, alles in TT. Wir lernen die explosive Bewegung in Position, bevor wir Leistung suchen.", "nl": "Kennismaking: zittende sprints van 15'''', versnellingen van 1'' en de eerste 30/30''s, allemaal in TT. We leren de explosieve beweging in houding voordat we vermogen zoeken.", "ja": "導入：シッティングで15''''のスプリント、1''の加速、最初の30/30、すべてTTで。パワーを求める前に、ポジションのまま爆発的な動きを学びます。", "tr": "Keşif: oturarak 15'''' sprintler, 1'' ataklar ve ilk 30/30''lar, hepsi TT''de. Güç aramadan önce pozisyonda patlayıcı hareketi öğreniyoruz."}, "2": {"fr": "Plus de répétitions sur chaque séance. La capacité anaérobie se développe ; la difficulté est de rester en TT quand les jambes et le souffle saturent.", "en": "More reps in each session. Anaerobic capacity develops; the challenge is staying in TT when your legs and breathing max out.", "es": "Más repeticiones en cada sesión. La capacidad anaeróbica se desarrolla; la dificultad es mantenerte en TT cuando las piernas y el aliento se saturan.", "it": "Più ripetute in ogni seduta. La capacità anaerobica si sviluppa; la difficoltà è restare in TT quando gambe e fiato sono saturi.", "pt": "Mais repetições em cada sessão. A capacidade anaeróbia se desenvolve; a dificuldade é ficar em TT quando as pernas e o fôlego saturam.", "de": "Mehr Wiederholungen pro Einheit. Die anaerobe Kapazität entwickelt sich; die Schwierigkeit ist, in TT zu bleiben, wenn Beine und Atem am Limit sind.", "nl": "Meer herhalingen per training. De anaerobe capaciteit ontwikkelt zich; de uitdaging is in TT te blijven als benen en adem verzadigd raken.", "ja": "各セッションで反復が増えます。無酸素能力が伸び、脚と呼吸が限界に達してもTTを保つことが課題です。", "tr": "Her antrenmanda daha fazla tekrar. Anaerobik kapasite gelişiyor; zorluk, bacaklar ve nefes doyduğunda TT''de kalmak."}, "3": {"fr": "Surcharge du premier cycle : 12 sprints, 10 relances, 3 séries de 30/30. C''est cette semaine qui crée le gain du cycle, la suivante le révèle.", "en": "First-cycle overload: 12 sprints, 10 surges, 3 sets of 30/30. This week creates the cycle''s gain; the next one reveals it.", "es": "Sobrecarga del primer ciclo: 12 sprints, 10 cambios de ritmo, 3 series de 30/30. Esta semana crea la mejora del ciclo; la siguiente la revela.", "it": "Sovraccarico del primo ciclo: 12 sprint, 10 rilanci, 3 serie di 30/30. È questa settimana che crea il progresso del ciclo, la successiva lo rivela.", "pt": "Sobrecarga do primeiro ciclo: 12 sprints, 10 retomadas, 3 séries de 30/30. É esta semana que cria o ganho do ciclo, a seguinte o revela.", "de": "Belastungsspitze des ersten Zyklus: 12 Sprints, 10 Antritte, 3 Serien 30/30. Diese Woche erzeugt den Fortschritt des Zyklus, die nächste macht ihn sichtbar.", "nl": "Piekbelasting van de eerste cyclus: 12 sprints, 10 versnellingen, 3 series 30/30. Deze week creëert de winst van de cyclus, de volgende maakt die zichtbaar.", "ja": "第1サイクルのオーバーロード：スプリント12本、加速10本、30/30を3セット。この週がサイクルの成果を生み、次の週がそれを引き出します。", "tr": "İlk döngünün yüklenmesi: 12 sprint, 10 atak, 3 set 30/30. Döngünün kazancını yaratan bu hafta, bir sonraki onu ortaya çıkarır."}, "4": {"fr": "Allègement : moins de répétitions, une endurance TT de 40''. La fraîcheur revient et les sprints doivent sortir plus fort qu''en semaine 1.", "en": "Lighter week: fewer reps, a 40'' TT endurance ride. Freshness comes back and your sprints should come out stronger than in week 1.", "es": "Semana más ligera: menos repeticiones, una resistencia en TT de 40''. La frescura vuelve y los sprints deben salir más fuertes que en la semana 1.", "it": "Scarico: meno ripetute, un endurance in TT di 40''. La freschezza torna e gli sprint devono uscire più forti che in settimana 1.", "pt": "Alívio: menos repetições, um endurance em TT de 40''. A disposição volta e os sprints devem sair mais fortes que na semana 1.", "de": "Entlastung: weniger Wiederholungen, 40'' TT-Grundlage. Die Frische kehrt zurück und die Sprints sollten stärker ausfallen als in Woche 1.", "nl": "Afbouw: minder herhalingen, 40'' duur in TT. De frisheid komt terug en de sprints moeten krachtiger zijn dan in week 1.", "ja": "軽めの週：反復を減らし、TTでのエンデュランス40''。フレッシュさが戻り、スプリントは1週目より強く出るはずです。", "tr": "Hafifletme: daha az tekrar, 40'' TT dayanıklılık. Tazelik geri geliyor ve sprintler 1. haftadakinden daha güçlü çıkmalı."}, "5": {"fr": "Deuxième cycle : les sprints passent à 20'''' et à 175 % FTP, les relances à 125 %. Plus long et plus fort, c''est la puissance maximale tenue en aéro qui progresse.", "en": "Second cycle: sprints go up to 20'''' and 175 % FTP, surges to 125 %. Longer and harder, it''s the maximum power you can hold in aero that improves.", "es": "Segundo ciclo: los sprints pasan a 20'''' y al 175 % FTP, los cambios de ritmo al 125 %. Más largos y más fuertes: lo que progresa es la potencia máxima sostenida en aero.", "it": "Secondo ciclo: gli sprint passano a 20'''' e al 175 % FTP, i rilanci al 125 %. Più lunghi e più forti: è la potenza massima tenuta in aero che cresce.", "pt": "Segundo ciclo: os sprints passam para 20'''' e 175 % FTP, as retomadas para 125 %. Mais longos e mais fortes, é a potência máxima sustentada em aero que evolui.", "de": "Zweiter Zyklus: Die Sprints steigen auf 20'''' und 175 % FTP, die Antritte auf 125 %. Länger und stärker – es wächst die in Aero-Position gehaltene Maximalleistung.", "nl": "Tweede cyclus: de sprints gaan naar 20'''' en 175 % FTP, de versnellingen naar 125 %. Langer en harder: het maximale vermogen in aerohouding groeit.", "ja": "第2サイクル：スプリントは20''''でFTPの175 %、加速は125 %に。より長く、より強く、エアロで保てる最大パワーが伸びます。", "tr": "İkinci döngü: sprintler 20'''' ve FTP''nin %175''ine, ataklar %125''e çıkıyor. Daha uzun ve daha güçlü, gelişen aero''da tutulan maksimum güç."}, "6": {"fr": "Volume en hausse (10 sprints, 10 relances, 3×10 30/30). Garde la récupération redressée complète entre les sprints : un sprint lent n''entraîne pas la puissance max.", "en": "Volume rises (10 sprints, 10 surges, 3×10 30/30). Keep the full upright recovery between sprints: a slow sprint doesn''t train max power.", "es": "El volumen sube (10 sprints, 10 cambios de ritmo, 3×10 30/30). Mantén la recuperación completa erguido entre sprints: un sprint lento no entrena la potencia máxima.", "it": "Volume in aumento (10 sprint, 10 rilanci, 3×10 30/30). Mantieni il recupero eretto completo tra gli sprint: uno sprint lento non allena la potenza massima.", "pt": "Volume em alta (10 sprints, 10 retomadas, 3×10 30/30). Mantenha a recuperação ereta completa entre os sprints: um sprint lento não treina a potência máxima.", "de": "Mehr Umfang (10 Sprints, 10 Antritte, 3×10 30/30). Erhol dich zwischen den Sprints vollständig aufrecht: Ein langsamer Sprint trainiert keine Maximalleistung.", "nl": "Meer volume (10 sprints, 10 versnellingen, 3×10 30/30). Herstel volledig rechtop tussen de sprints: een trage sprint traint geen maximaal vermogen.", "ja": "ボリューム増（スプリント10本、加速10本、3×10 30/30）。スプリント間はアップライトで完全に回復すること：遅いスプリントでは最大パワーは鍛えられません。", "tr": "Hacim artıyor (10 sprint, 10 atak, 3×10 30/30). Sprintler arasında dik pozisyonda tam toparlan: yavaş bir sprint maksimum gücü geliştirmez."}, "7": {"fr": "Pic du plan : 12 sprints à 180 %, 12 relances, 4 séries de 30/30. C''est la semaine la plus exigeante, en jambes comme en tenue de position.", "en": "Peak of the plan: 12 sprints at 180 %, 12 surges, 4 sets of 30/30. The most demanding week, for your legs as much as for holding position.", "es": "Pico del plan: 12 sprints al 180 %, 12 cambios de ritmo, 4 series de 30/30. Es la semana más exigente, tanto para las piernas como para mantener la posición.", "it": "Picco del piano: 12 sprint al 180 %, 12 rilanci, 4 serie di 30/30. È la settimana più impegnativa, per le gambe come per la tenuta della posizione.", "pt": "Pico do plano: 12 sprints a 180 %, 12 retomadas, 4 séries de 30/30. É a semana mais exigente, tanto nas pernas quanto na sustentação da posição.", "de": "Höhepunkt des Plans: 12 Sprints bei 180 %, 12 Antritte, 4 Serien 30/30. Die anspruchsvollste Woche, für die Beine wie für die Haltung.", "nl": "Hoogtepunt van het plan: 12 sprints op 180 %, 12 versnellingen, 4 series 30/30. De zwaarste week, voor de benen én voor het vasthouden van de houding.", "ja": "プランのピーク：180 %でスプリント12本、加速12本、30/30を4セット。脚にもポジション維持にも最も厳しい週です。", "tr": "Planın zirvesi: %180''de 12 sprint, 12 atak, 4 set 30/30. Hem bacaklar hem pozisyon tutuşu için en zorlu hafta."}, "8": {"fr": "Affûtage : volume minimal, intensité intacte. Tu termines frais, avec une puissance max en TT nettement au-dessus de celle de la semaine 1.", "en": "Taper: minimal volume, intensity intact. You finish fresh, with max power in TT well above week 1''s.", "es": "Puesta a punto: volumen mínimo, intensidad intacta. Terminas fresco, con una potencia máxima en TT claramente superior a la de la semana 1.", "it": "Scarico: volume minimo, intensità intatta. Finisci fresco, con una potenza massima in TT nettamente sopra quella della settimana 1.", "pt": "Polimento: volume mínimo, intensidade intacta. Você termina descansado, com uma potência máxima em TT bem acima da semana 1.", "de": "Tapering: minimaler Umfang, Intensität unverändert. Du beendest den Plan frisch, mit einer Maximalleistung in TT deutlich über der von Woche 1.", "nl": "Taperen: minimaal volume, intensiteit intact. Je eindigt fris, met een maximaal vermogen in TT duidelijk boven dat van week 1.", "ja": "調整（テーパー）：ボリュームは最小、強度はそのまま。フレッシュな状態で終え、TTでの最大パワーは1週目を明らかに上回ります。", "tr": "Yarış öncesi yük azaltma: minimum hacim, yoğunluk aynen. Taze bitiriyorsun, TT''deki maksimum gücün 1. haftanınkinin belirgin şekilde üstünde."}}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Mise en route : sweet spot 3×12'', seuil 4×8'', puissance critique 5×3'', tout en TT. On établit ce que tu produis couché avant d''allonger les blocs.", "en": "Getting started: sweet spot 3×12'', threshold 4×8'', critical power 5×3'', all in TT. We establish what you produce tucked low before lengthening the blocks.", "es": "Puesta en marcha: sweet spot 3×12'', umbral 4×8'', potencia crítica 5×3'', todo en TT. Establecemos lo que produces acoplado antes de alargar los bloques.", "it": "Avvio: sweet spot 3×12'', soglia 4×8'', potenza critica 5×3'', tutto in TT. Stabiliamo ciò che produci in posizione aero prima di allungare i blocchi.", "pt": "Início: sweet spot 3×12'', limiar 4×8'', potência crítica 5×3'', tudo em TT. Estabelecemos o que você produz em posição aero antes de alongar os blocos.", "de": "Einstieg: Sweet Spot 3×12'', Schwelle 4×8'', kritische Leistung 5×3'', alles in TT. Wir ermitteln, was du liegend leistest, bevor die Blöcke länger werden.", "nl": "Instap: sweet spot 3×12'', drempel 4×8'', kritisch vermogen 5×3'', alles in TT. We bepalen wat je liggend levert voordat de blokken langer worden.", "ja": "導入：スイートスポット3×12''、閾値4×8''、クリティカルパワー5×3''、すべてTTで。ブロックを伸ばす前に、伏せた姿勢で出せるパワーを把握します。", "tr": "Başlangıç: sweet spot 3×12'', eşik 4×8'', kritik güç 5×3'', hepsi TT''de. Blokları uzatmadan önce yatık pozisyonda ne ürettiğini belirliyoruz."}, "2": {"fr": "Les blocs s''allongent et les sur-sous apparaissent : changer d''intensité sans bouger de position, comme sur un parcours vallonné.", "en": "Blocks get longer and over-unders appear: changing intensity without moving out of position, like on a rolling course.", "es": "Los bloques se alargan y aparecen los sobre-bajo: cambiar de intensidad sin moverte de la posición, como en un recorrido ondulado.", "it": "I blocchi si allungano e compaiono i sopra-sotto: cambiare intensità senza muoversi dalla posizione, come su un percorso ondulato.", "pt": "Os blocos se alongam e aparecem os acima-abaixo: mudar de intensidade sem sair da posição, como num percurso ondulado.", "de": "Die Blöcke werden länger und die Over-Under kommen: die Intensität wechseln, ohne die Position zu verändern, wie auf einer welligen Strecke.", "nl": "De blokken worden langer en de over-unders verschijnen: van intensiteit wisselen zonder je houding te veranderen, zoals op een heuvelachtig parcours.", "ja": "ブロックが伸び、オーバーアンダーが登場：起伏のあるコースのように、ポジションを動かさずに強度を変えます。", "tr": "Bloklar uzuyor ve üst-altlar geliyor: inişli çıkışlı bir parkurdaki gibi, pozisyonu bozmadan yoğunluk değiştirmek."}, "3": {"fr": "Surcharge du premier cycle : 2×20'' sweet spot, 3×12'' seuil, 5×4'' puissance critique. La fatigue s''accumule volontairement, la semaine suivante la fait disparaître.", "en": "First-cycle overload: 2×20'' sweet spot, 3×12'' threshold, 5×4'' critical power. Fatigue builds on purpose; the next week makes it disappear.", "es": "Sobrecarga del primer ciclo: 2×20'' sweet spot, 3×12'' umbral, 5×4'' potencia crítica. La fatiga se acumula a propósito; la semana siguiente la hace desaparecer.", "it": "Sovraccarico del primo ciclo: 2×20'' sweet spot, 3×12'' soglia, 5×4'' potenza critica. La fatica si accumula di proposito, la settimana successiva la fa sparire.", "pt": "Sobrecarga do primeiro ciclo: 2×20'' sweet spot, 3×12'' limiar, 5×4'' potência crítica. O cansaço se acumula de propósito, a semana seguinte o faz desaparecer.", "de": "Belastungsspitze des ersten Zyklus: 2×20'' Sweet Spot, 3×12'' Schwelle, 5×4'' kritische Leistung. Die Müdigkeit summiert sich bewusst, die nächste Woche baut sie ab.", "nl": "Piekbelasting van de eerste cyclus: 2×20'' sweet spot, 3×12'' drempel, 5×4'' kritisch vermogen. De vermoeidheid stapelt zich bewust op, de volgende week laat haar verdwijnen.", "ja": "第1サイクルのオーバーロード：スイートスポット2×20''、閾値3×12''、クリティカルパワー5×4''。疲労は意図的に蓄積させ、次の週で解消します。", "tr": "İlk döngünün yüklenmesi: 2×20'' sweet spot, 3×12'' eşik, 5×4'' kritik güç. Yorgunluk bilerek birikiyor, bir sonraki hafta onu siliyor."}, "4": {"fr": "Allègement : volume divisé par deux, intensité conservée sur des blocs courts. C''est pendant cette semaine que la FTP monte réellement.", "en": "Lighter week: volume halved, intensity kept on short blocks. This is the week your FTP actually rises.", "es": "Semana más ligera: volumen a la mitad, intensidad mantenida en bloques cortos. Es durante esta semana cuando la FTP sube de verdad.", "it": "Scarico: volume dimezzato, intensità mantenuta su blocchi brevi. È durante questa settimana che la FTP sale davvero.", "pt": "Alívio: volume pela metade, intensidade mantida em blocos curtos. É durante esta semana que a FTP realmente sobe.", "de": "Entlastung: Umfang halbiert, Intensität auf kurzen Blöcken beibehalten. In dieser Woche steigt die FTP tatsächlich.", "nl": "Afbouw: volume gehalveerd, intensiteit behouden op korte blokken. Tijdens deze week stijgt de FTP echt.", "ja": "軽めの週：ボリュームは半分、短いブロックで強度は維持。FTPが実際に上がるのはこの週です。", "tr": "Hafifletme: hacim yarıya iniyor, kısa bloklarda yoğunluk korunuyor. FTP''nin gerçekten yükseldiği hafta bu."}, "5": {"fr": "Deuxième cycle : 3×20'' sweet spot et 3×15'' au seuil. Les blocs approchent la durée d''un CLM ; garder la tête basse au-delà de 15'' devient l''enjeu.", "en": "Second cycle: 3×20'' sweet spot and 3×15'' at threshold. Blocks approach the length of a TT; keeping your head down beyond 15'' becomes the challenge.", "es": "Segundo ciclo: 3×20'' sweet spot y 3×15'' en umbral. Los bloques se acercan a la duración de una CRI; mantener la cabeza baja más allá de 15'' se convierte en el reto.", "it": "Secondo ciclo: 3×20'' sweet spot e 3×15'' alla soglia. I blocchi si avvicinano alla durata di una crono; tenere la testa bassa oltre i 15'' diventa la sfida.", "pt": "Segundo ciclo: 3×20'' sweet spot e 3×15'' no limiar. Os blocos se aproximam da duração de um contrarrelógio; manter a cabeça baixa além de 15'' vira o desafio.", "de": "Zweiter Zyklus: 3×20'' Sweet Spot und 3×15'' an der Schwelle. Die Blöcke nähern sich der Dauer eines Zeitfahrens; den Kopf über 15'' hinaus unten zu halten, wird zur Herausforderung.", "nl": "Tweede cyclus: 3×20'' sweet spot en 3×15'' op drempel. De blokken naderen de duur van een tijdrit; je hoofd langer dan 15'' laag houden wordt de uitdaging.", "ja": "第2サイクル：スイートスポット3×20''と閾値3×15''。ブロックはタイムトライアルの時間に近づきます。15''を超えて頭を低く保つことが課題です。", "tr": "İkinci döngü: 3×20'' sweet spot ve eşikte 3×15''. Bloklar bir zamana karşı yarışının süresine yaklaşıyor; 15'' geçince başı aşağıda tutmak asıl mesele."}, "6": {"fr": "2×30'' en sweet spot, 2×20'' au seuil, 5×5'' à 108 %. Les efforts longs en TT sont ceux qui font le plus progresser la FTP en aéro.", "en": "2×30'' sweet spot, 2×20'' at threshold, 5×5'' at 108 %. Long efforts in TT are the ones that improve your FTP in aero the most.", "es": "2×30'' en sweet spot, 2×20'' en umbral, 5×5'' al 108 %. Los esfuerzos largos en TT son los que más hacen progresar la FTP en aero.", "it": "2×30'' in sweet spot, 2×20'' alla soglia, 5×5'' al 108 %. Gli sforzi lunghi in TT sono quelli che fanno crescere di più la FTP in aero.", "pt": "2×30'' em sweet spot, 2×20'' no limiar, 5×5'' a 108 %. Os esforços longos em TT são os que mais fazem evoluir a FTP em aero.", "de": "2×30'' Sweet Spot, 2×20'' an der Schwelle, 5×5'' bei 108 %. Lange Belastungen in TT verbessern die FTP in Aero-Position am stärksten.", "nl": "2×30'' sweet spot, 2×20'' op drempel, 5×5'' op 108 %. Lange inspanningen in TT laten de FTP in aerohouding het meest vooruitgaan.", "ja": "スイートスポット2×30''、閾値2×20''、108 %で5×5''。エアロでのFTPを最も伸ばすのは、TTでの長い努力です。", "tr": "Sweet spot''ta 2×30'', eşikte 2×20'', %108''de 5×5''. Aero''da FTP''yi en çok geliştiren, TT''deki uzun eforlardır."}, "7": {"fr": "Pic du plan : 3×25'' sweet spot, 3×20'' au seuil, 6×5'' à la puissance critique. C''est la semaine la plus dure, tout ce que tu tiens ici sera acquis.", "en": "Peak of the plan: 3×25'' sweet spot, 3×20'' at threshold, 6×5'' at critical power. The hardest week; whatever you hold here will stick.", "es": "Pico del plan: 3×25'' sweet spot, 3×20'' en umbral, 6×5'' a potencia crítica. Es la semana más dura; todo lo que aguantes aquí quedará adquirido.", "it": "Picco del piano: 3×25'' sweet spot, 3×20'' alla soglia, 6×5'' alla potenza critica. È la settimana più dura, tutto ciò che reggi qui sarà acquisito.", "pt": "Pico do plano: 3×25'' sweet spot, 3×20'' no limiar, 6×5'' na potência crítica. É a semana mais dura, tudo o que você segurar aqui estará conquistado.", "de": "Höhepunkt des Plans: 3×25'' Sweet Spot, 3×20'' an der Schwelle, 6×5'' bei kritischer Leistung. Die härteste Woche – alles, was du hier hältst, sitzt.", "nl": "Hoogtepunt van het plan: 3×25'' sweet spot, 3×20'' op drempel, 6×5'' op kritisch vermogen. De zwaarste week: alles wat je hier volhoudt, is verworven.", "ja": "プランのピーク：スイートスポット3×25''、閾値3×20''、クリティカルパワー6×5''。最もきつい週で、ここで保てたものはすべて身につきます。", "tr": "Planın zirvesi: 3×25'' sweet spot, eşikte 3×20'', kritik güçte 6×5''. En zor hafta, burada tuttuğun her şey kalıcı olacak."}, "8": {"fr": "Semaine allégée : blocs courts, une endurance TT. Tu récupères pour que ta nouvelle FTP en aéro s''exprime pleinement.", "en": "Lighter week: short blocks, one TT endurance ride. You recover so your new aero FTP can fully show.", "es": "Semana más ligera: bloques cortos, una resistencia en TT. Recuperas para que tu nueva FTP en aero se exprese plenamente.", "it": "Settimana di scarico: blocchi brevi, un endurance in TT. Recuperi perché la tua nuova FTP in aero si esprima pienamente.", "pt": "Semana mais leve: blocos curtos, um endurance em TT. Você recupera para que sua nova FTP em aero se expresse plenamente.", "de": "Entlastungswoche: kurze Blöcke, eine TT-Grundlageneinheit. Du erholst dich, damit deine neue FTP in Aero-Position voll zur Geltung kommt.", "nl": "Lichtere week: korte blokken, één duurtraining in TT. Je herstelt zodat je nieuwe FTP in aerohouding volledig tot uiting komt.", "ja": "軽めの週：短いブロックとTTでのエンデュランス。回復して、エアロでの新しいFTPを存分に発揮できるようにします。", "tr": "Hafif hafta: kısa bloklar, bir TT dayanıklılık. Aero''daki yeni FTP''nin tam olarak ortaya çıkması için toparlanıyorsun."}}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Bases du CLM : seuil, PMA et une première simulation à l''allure du CLM en 3×6''. On découvre l''intensité de course en position, sur des efforts courts.", "en": "TT basics: threshold, VO2max and a first simulation at TT pace as 3×6''. You discover race intensity in position, on short efforts.", "es": "Bases de la CRI: umbral, VO2max y una primera simulación a ritmo de CRI en 3×6''. Descubres la intensidad de carrera en posición, con esfuerzos cortos.", "it": "Basi della crono: soglia, VO2max e una prima simulazione al ritmo crono in 3×6''. Scopri l''intensità di gara in posizione, su sforzi brevi.", "pt": "Bases do contrarrelógio: limiar, VO2max e uma primeira simulação no ritmo de contrarrelógio em 3×6''. Você descobre a intensidade de prova na posição, em esforços curtos.", "de": "Zeitfahr-Grundlagen: Schwelle, VO2max und eine erste Simulation im Zeitfahrtempo in 3×6''. Wir lernen die Wettkampfintensität in Position bei kurzen Belastungen kennen.", "nl": "Tijdritbasis: drempel, VO2max en een eerste simulatie op tijdrittempo in 3×6''. We maken kennis met wedstrijdintensiteit in houding, op korte inspanningen.", "ja": "タイムトライアルの基礎：閾値、VO2max、そしてTTのペースで3×6''の最初のシミュレーション。短い努力で、ポジションのままレース強度を体験します。", "tr": "Zamana karşının temelleri: eşik, VO2max ve zamana karşı temposunda 3×6'' ilk simülasyon. Kısa eforlarla yarış yoğunluğunu pozisyonda keşfediyoruz."}, "2": {"fr": "Les simulations passent à 3×8'' et une sortie longue en TT entretient l''endurance. Le seuil et la PMA restent les deux moteurs du CLM court.", "en": "Simulations go up to 3×8'' and a long ride in TT maintains endurance. Threshold and VO2max remain the two engines of a short TT.", "es": "Las simulaciones pasan a 3×8'' y una salida larga en TT mantiene la resistencia. El umbral y el VO2max siguen siendo los dos motores de la CRI corta.", "it": "Le simulazioni passano a 3×8'' e un''uscita lunga in TT mantiene la resistenza. Soglia e VO2max restano i due motori della crono breve.", "pt": "As simulações passam para 3×8'' e um treino longo em TT mantém a resistência. O limiar e o VO2max continuam sendo os dois motores do contrarrelógio curto.", "de": "Die Simulationen steigen auf 3×8'' und eine lange Fahrt in TT erhält die Ausdauer. Schwelle und VO2max bleiben die beiden Motoren des kurzen Zeitfahrens.", "nl": "De simulaties gaan naar 3×8'' en een lange rit in TT onderhoudt het uithoudingsvermogen. Drempel en VO2max blijven de twee motoren van de korte tijdrit.", "ja": "シミュレーションは3×8''になり、TTでのロングライドで持久力を維持します。閾値とVO2maxが短いタイムトライアルの2つのエンジンです。", "tr": "Simülasyonlar 3×8'' oluyor ve TT''de bir uzun sürüş dayanıklılığı koruyor. Eşik ve VO2max, kısa zamana karşının iki motoru olarak kalıyor."}, "3": {"fr": "Surcharge du premier cycle : sweet spot 2×20'', PMA 5×5'', allure CLM en 2×12''. Ton corps apprend à tenir l''allure de course plus longtemps.", "en": "First-cycle overload: sweet spot 2×20'', VO2max 5×5'', TT pace as 2×12''. Your body learns to hold race pace for longer.", "es": "Sobrecarga del primer ciclo: sweet spot 2×20'', VO2max 5×5'', ritmo de CRI en 2×12''. Tu cuerpo aprende a mantener el ritmo de carrera durante más tiempo.", "it": "Sovraccarico del primo ciclo: sweet spot 2×20'', VO2max 5×5'', ritmo crono in 2×12''. Il tuo corpo impara a tenere il ritmo di gara più a lungo.", "pt": "Sobrecarga do primeiro ciclo: sweet spot 2×20'', VO2max 5×5'', ritmo de contrarrelógio em 2×12''. Seu corpo aprende a segurar o ritmo de prova por mais tempo.", "de": "Belastungsspitze des ersten Zyklus: Sweet Spot 2×20'', VO2max 5×5'', Zeitfahrtempo in 2×12''. Dein Körper lernt, das Wettkampftempo länger zu halten.", "nl": "Piekbelasting van de eerste cyclus: sweet spot 2×20'', VO2max 5×5'', tijdrittempo in 2×12''. Je lichaam leert het wedstrijdtempo langer vol te houden.", "ja": "第1サイクルのオーバーロード：スイートスポット2×20''、VO2max 5×5''、TTペースで2×12''。体がレースペースをより長く保つことを学びます。", "tr": "İlk döngünün yüklenmesi: sweet spot 2×20'', VO2max 5×5'', zamana karşı temposunda 2×12''. Vücudun yarış temposunu daha uzun tutmayı öğreniyor."}, "4": {"fr": "Allègement : une séance en moins, blocs courts. La fraîcheur revient avant d''aborder les simulations longues.", "en": "Lighter week: one session fewer, short blocks. Freshness comes back before tackling the long simulations.", "es": "Semana más ligera: una sesión menos, bloques cortos. La frescura vuelve antes de abordar las simulaciones largas.", "it": "Scarico: una seduta in meno, blocchi brevi. La freschezza torna prima di affrontare le simulazioni lunghe.", "pt": "Alívio: uma sessão a menos, blocos curtos. A disposição volta antes de encarar as simulações longas.", "de": "Entlastung: eine Einheit weniger, kurze Blöcke. Die Frische kehrt zurück, bevor die langen Simulationen beginnen.", "nl": "Afbouw: één training minder, korte blokken. De frisheid komt terug voordat de lange simulaties beginnen.", "ja": "軽めの週：セッションを1回減らし、短いブロック。長いシミュレーションに入る前にフレッシュさを取り戻します。", "tr": "Hafifletme: bir antrenman eksik, kısa bloklar. Uzun simülasyonlara geçmeden önce tazelik geri geliyor."}, "5": {"fr": "Deuxième cycle : 2×20'' au seuil, puissance critique et 2×15'' à l''allure CLM. On se rapproche de la durée d''une course de 10 à 20 km.", "en": "Second cycle: 2×20'' at threshold, critical power and 2×15'' at TT pace. We get closer to the duration of a 10 to 20 km race.", "es": "Segundo ciclo: 2×20'' en umbral, potencia crítica y 2×15'' a ritmo de CRI. Nos acercamos a la duración de una carrera de 10 a 20 km.", "it": "Secondo ciclo: 2×20'' alla soglia, potenza critica e 2×15'' al ritmo crono. Ci si avvicina alla durata di una gara di 10-20 km.", "pt": "Segundo ciclo: 2×20'' no limiar, potência crítica e 2×15'' no ritmo de contrarrelógio. Nos aproximamos da duração de uma prova de 10 a 20 km.", "de": "Zweiter Zyklus: 2×20'' an der Schwelle, kritische Leistung und 2×15'' im Zeitfahrtempo. Wir nähern uns der Dauer eines Rennens über 10 bis 20 km.", "nl": "Tweede cyclus: 2×20'' op drempel, kritisch vermogen en 2×15'' op tijdrittempo. We komen dicht bij de duur van een wedstrijd van 10 tot 20 km.", "ja": "第2サイクル：閾値2×20''、クリティカルパワー、TTペースで2×15''。10〜20 kmのレースの時間に近づきます。", "tr": "İkinci döngü: eşikte 2×20'', kritik güç ve zamana karşı temposunda 2×15''. 10-20 km''lik bir yarışın süresine yaklaşıyoruz."}, "6": {"fr": "Première simulation d''un seul tenant : 20'' à l''allure CLM. C''est l''épreuve de vérité pour la position : ne te relève pas quand la douleur monte.", "en": "First unbroken simulation: 20'' at TT pace. This is the moment of truth for the position: don''t sit up when the pain rises.", "es": "Primera simulación de una sola vez: 20'' a ritmo de CRI. Es la prueba de fuego para la posición: no te irgas cuando aumente el dolor.", "it": "Prima simulazione tutta d''un fiato: 20'' al ritmo crono. È la prova della verità per la posizione: non alzarti quando il dolore sale.", "pt": "Primeira simulação de uma vez só: 20'' no ritmo de contrarrelógio. É a prova de fogo para a posição: não se levante quando a dor aumentar.", "de": "Erste Simulation am Stück: 20'' im Zeitfahrtempo. Die Stunde der Wahrheit für die Position: Richte dich nicht auf, wenn der Schmerz steigt.", "nl": "Eerste simulatie aan één stuk: 20'' op tijdrittempo. Het moment van de waarheid voor de houding: kom niet rechtop als de pijn toeneemt.", "ja": "初めての一続きのシミュレーション：TTペースで20''。ポジションの真価が問われます。痛みが増しても起き上がらないこと。", "tr": "İlk kesintisiz simülasyon: zamana karşı temposunda 20''. Pozisyon için gerçeğin anı: acı arttığında doğrulma."}, "7": {"fr": "Pic du plan : 25'' d''affilée à 100 % FTP en TT, seuil 3×15'' et la plus longue sortie. C''est la répétition générale de la course.", "en": "Peak of the plan: 25'' straight at 100 % FTP in TT, threshold 3×15'' and the longest ride. This is the dress rehearsal for the race.", "es": "Pico del plan: 25'' seguidos al 100 % FTP en TT, umbral 3×15'' y la salida más larga. Es el ensayo general de la carrera.", "it": "Picco del piano: 25'' di fila al 100 % FTP in TT, soglia 3×15'' e l''uscita più lunga. È la prova generale della gara.", "pt": "Pico do plano: 25'' seguidos a 100 % FTP em TT, limiar 3×15'' e o treino mais longo. É o ensaio geral da prova.", "de": "Höhepunkt des Plans: 25'' am Stück bei 100 % FTP in TT, Schwelle 3×15'' und die längste Fahrt. Die Generalprobe für das Rennen.", "nl": "Hoogtepunt van het plan: 25'' aan één stuk op 100 % FTP in TT, drempel 3×15'' en de langste rit. De generale repetitie van de wedstrijd.", "ja": "プランのピーク：TTでFTPの100 %を25''連続、閾値3×15''、最長のロングライド。レースのリハーサルです。", "tr": "Planın zirvesi: TT''de FTP''nin %100''ünde kesintisiz 25'', eşik 3×15'' ve en uzun sürüş. Yarışın genel provası bu."}, "8": {"fr": "Affûtage : volume réduit, quelques efforts à l''allure de course pour garder le rythme. Tu arrives frais le jour du CLM.", "en": "Taper: reduced volume, a few efforts at race pace to keep the rhythm. You arrive fresh on TT day.", "es": "Puesta a punto: volumen reducido, algunos esfuerzos a ritmo de carrera para mantener el ritmo. Llegas fresco el día de la CRI.", "it": "Scarico: volume ridotto, qualche sforzo al ritmo di gara per mantenere il passo. Arrivi fresco il giorno della crono.", "pt": "Polimento: volume reduzido, alguns esforços no ritmo de prova para manter o embalo. Você chega descansado no dia do contrarrelógio.", "de": "Tapering: weniger Umfang, einige Belastungen im Wettkampftempo, um den Rhythmus zu halten. Du gehst frisch ins Zeitfahren.", "nl": "Taperen: minder volume, enkele inspanningen op wedstrijdtempo om het ritme te houden. Je komt fris aan de start van de tijdrit.", "ja": "調整（テーパー）：ボリュームを減らし、リズムを保つためにレースペースでの努力を少し。タイムトライアル当日はフレッシュな状態で臨みます。", "tr": "Yarış öncesi yük azaltma: azaltılmış hacim, ritmi korumak için yarış temposunda birkaç efor. Zamana karşı günü taze geliyorsun."}}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Adaptation : allure triathlon (85-90 % FTP) en 2×15'', sweet spot et PMA. On installe l''allure de course en TT sur des blocs courts.", "en": "Adaptation: triathlon pace (85-90 % FTP) as 2×15'', sweet spot and VO2max. We settle race pace in TT on short blocks.", "es": "Adaptación: ritmo de triatlón (85-90 % FTP) en 2×15'', sweet spot y VO2max. Asentamos el ritmo de carrera en TT con bloques cortos.", "it": "Adattamento: ritmo triathlon (85-90 % FTP) in 2×15'', sweet spot e VO2max. Fissiamo il ritmo di gara in TT su blocchi brevi.", "pt": "Adaptação: ritmo de triatlo (85-90 % FTP) em 2×15'', sweet spot e VO2max. Fixamos o ritmo de prova em TT em blocos curtos.", "de": "Anpassung: Triathlontempo (85-90 % FTP) in 2×15'', Sweet Spot und VO2max. Wir festigen das Wettkampftempo in TT auf kurzen Blöcken.", "nl": "Aanpassing: triatlontempo (85-90 % FTP) in 2×15'', sweet spot en VO2max. We leren het wedstrijdtempo aan in TT op korte blokken.", "ja": "適応：トライアスロンのペース（FTPの85〜90 %）で2×15''、スイートスポット、VO2max。短いブロックでTTでのレースペースを定着させます。", "tr": "Uyum: triatlon temposunda (FTP''nin %85-90''ı) 2×15'', sweet spot ve VO2max. Yarış temposunu kısa bloklarla TT''de oturtuyoruz."}, "2": {"fr": "Les blocs à l''allure triathlon passent à 20'' et le tempo arrive. L''enjeu est la nuque : elle fatigue avant les jambes à cette intensité.", "en": "Triathlon-pace blocks go up to 20'' and tempo arrives. The key is your neck: at this intensity it tires before your legs.", "es": "Los bloques a ritmo de triatlón pasan a 20'' y llega el tempo. El reto es la nuca: a esta intensidad se fatiga antes que las piernas.", "it": "I blocchi al ritmo triathlon passano a 20'' e arriva il ritmo tempo. La sfida è il collo: a questa intensità si stanca prima delle gambe.", "pt": "Os blocos no ritmo de triatlo passam para 20'' e chega o ritmo tempo. O desafio é a nuca: ela cansa antes das pernas nessa intensidade.", "de": "Die Blöcke im Triathlontempo steigen auf 20'' und Tempo kommt hinzu. Die Herausforderung ist der Nacken: Er ermüdet bei dieser Intensität vor den Beinen.", "nl": "De blokken op triatlontempo gaan naar 20'' en er komt tempo bij. De uitdaging is je nek: die raakt bij deze intensiteit eerder vermoeid dan je benen.", "ja": "トライアスロンペースのブロックは20''になり、テンポが加わります。課題は首：この強度では脚より先に疲れます。", "tr": "Triatlon temposundaki bloklar 20'' oluyor ve tempo geliyor. Mesele ense: bu yoğunlukta bacaklardan önce yorulur."}, "3": {"fr": "Surcharge du premier cycle : 3×20'' à l''allure triathlon et 2 h 15 de sortie longue. C''est la charge qui prépare le deuxième cycle.", "en": "First-cycle overload: 3×20'' at triathlon pace and a 2 h 15 long ride. This is the load that prepares the second cycle.", "es": "Sobrecarga del primer ciclo: 3×20'' a ritmo de triatlón y 2 h 15 de salida larga. Es la carga que prepara el segundo ciclo.", "it": "Sovraccarico del primo ciclo: 3×20'' al ritmo triathlon e 2 h 15 di uscita lunga. È il carico che prepara il secondo ciclo.", "pt": "Sobrecarga do primeiro ciclo: 3×20'' no ritmo de triatlo e 2 h 15 de treino longo. É a carga que prepara o segundo ciclo.", "de": "Belastungsspitze des ersten Zyklus: 3×20'' im Triathlontempo und 2 h 15 lange Fahrt. Diese Belastung bereitet den zweiten Zyklus vor.", "nl": "Piekbelasting van de eerste cyclus: 3×20'' op triatlontempo en een lange rit van 2 u 15. Deze belasting bereidt de tweede cyclus voor.", "ja": "第1サイクルのオーバーロード：トライアスロンペースで3×20''、2時間15分のロングライド。第2サイクルに備える負荷です。", "tr": "İlk döngünün yüklenmesi: triatlon temposunda 3×20'' ve 2 sa 15 uzun sürüş. İkinci döngüyü hazırlayan yük bu."}, "4": {"fr": "Allègement : une séance en moins, blocs ramenés à 15''. La récupération fait monter la forme avant les blocs longs.", "en": "Lighter week: one session fewer, blocks back to 15''. Recovery lifts your form before the long blocks.", "es": "Semana más ligera: una sesión menos, bloques reducidos a 15''. La recuperación hace subir la forma antes de los bloques largos.", "it": "Scarico: una seduta in meno, blocchi riportati a 15''. Il recupero fa salire la forma prima dei blocchi lunghi.", "pt": "Alívio: uma sessão a menos, blocos de volta a 15''. A recuperação faz a forma subir antes dos blocos longos.", "de": "Entlastung: eine Einheit weniger, Blöcke zurück auf 15''. Die Erholung steigert die Form vor den langen Blöcken.", "nl": "Afbouw: één training minder, blokken terug naar 15''. Het herstel verbetert je vorm voor de lange blokken.", "ja": "軽めの週：セッションを1回減らし、ブロックは15''に戻します。回復によって、長いブロックの前にコンディションが上がります。", "tr": "Hafifletme: bir antrenman eksik, bloklar 15'' oluyor. Toparlanma, uzun bloklardan önce formu yükseltiyor."}, "5": {"fr": "Deuxième cycle : 2×30'' à l''allure triathlon et du seuil. Les blocs s''approchent de la durée du vélo d''un triathlon M.", "en": "Second cycle: 2×30'' at triathlon pace plus threshold. Blocks approach the length of the bike leg of an Olympic-distance triathlon.", "es": "Segundo ciclo: 2×30'' a ritmo de triatlón y umbral. Los bloques se acercan a la duración del segmento ciclista de un triatlón olímpico.", "it": "Secondo ciclo: 2×30'' al ritmo triathlon e soglia. I blocchi si avvicinano alla durata della frazione bici di un triathlon olimpico.", "pt": "Segundo ciclo: 2×30'' no ritmo de triatlo e limiar. Os blocos se aproximam da duração do ciclismo de um triatlo olímpico.", "de": "Zweiter Zyklus: 2×30'' im Triathlontempo und Schwelle. Die Blöcke nähern sich der Raddauer eines Triathlons über die Olympische Distanz.", "nl": "Tweede cyclus: 2×30'' op triatlontempo en drempel. De blokken naderen de fietsduur van een triatlon op de olympische afstand.", "ja": "第2サイクル：トライアスロンペースで2×30''と閾値。ブロックはオリンピックディスタンスのバイクの時間に近づきます。", "tr": "İkinci döngü: triatlon temposunda 2×30'' ve eşik. Bloklar M mesafe triatlonun bisiklet süresine yaklaşıyor."}, "6": {"fr": "45'' d''affilée à l''allure triathlon. Pense à la course à pied qui suit : une position tenue sans crispation laisse des jambes pour courir.", "en": "45'' straight at triathlon pace. Think about the run that follows: a position held without tension leaves legs for running.", "es": "45'' seguidos a ritmo de triatlón. Piensa en la carrera a pie que viene después: una posición mantenida sin tensión te deja piernas para correr.", "it": "45'' di fila al ritmo triathlon. Pensa alla corsa che segue: una posizione tenuta senza tensioni lascia gambe per correre.", "pt": "45'' seguidos no ritmo de triatlo. Pense na corrida que vem depois: uma posição sustentada sem tensão deixa pernas para correr.", "de": "45'' am Stück im Triathlontempo. Denk an den Lauf danach: Eine Position ohne Verkrampfung lässt dir Beine zum Laufen.", "nl": "45'' aan één stuk op triatlontempo. Denk aan het lopen daarna: een houding zonder verkramping laat je benen over om te lopen.", "ja": "トライアスロンペースで45''連続。続くランを考えて：力まずに保ったポジションは、走るための脚を残します。", "tr": "Triatlon temposunda kesintisiz 45''. Ardından gelen koşuyu düşün: kasılmadan tutulan pozisyon koşmak için bacak bırakır."}, "7": {"fr": "Pic du plan : 60'' d''affilée à l''allure triathlon, soit le vélo d''un 40 km. C''est la simulation de course.", "en": "Peak of the plan: 60'' straight at triathlon pace, the bike leg of a 40 km. This is the race simulation.", "es": "Pico del plan: 60'' seguidos a ritmo de triatlón, es decir, el segmento ciclista de 40 km. Es la simulación de carrera.", "it": "Picco del piano: 60'' di fila al ritmo triathlon, cioè la frazione bici di 40 km. È la simulazione di gara.", "pt": "Pico do plano: 60'' seguidos no ritmo de triatlo, ou seja, o ciclismo de 40 km. É a simulação de prova.", "de": "Höhepunkt des Plans: 60'' am Stück im Triathlontempo, also die Radstrecke über 40 km. Das ist die Wettkampfsimulation.", "nl": "Hoogtepunt van het plan: 60'' aan één stuk op triatlontempo, oftewel de fietsproef van 40 km. Dit is de wedstrijdsimulatie.", "ja": "プランのピーク：トライアスロンペースで60''連続、つまり40 kmのバイク。レースのシミュレーションです。", "tr": "Planın zirvesi: triatlon temposunda kesintisiz 60'', yani 40 km''lik bisiklet. Yarış simülasyonu bu."}, "8": {"fr": "Affûtage : volume minimal, quelques rappels d''allure. Tu arrives frais pour la course.", "en": "Taper: minimal volume, a few pace reminders. You arrive fresh for the race.", "es": "Puesta a punto: volumen mínimo, algunos recordatorios de ritmo. Llegas fresco a la carrera.", "it": "Scarico: volume minimo, qualche richiamo di ritmo. Arrivi fresco alla gara.", "pt": "Polimento: volume mínimo, alguns lembretes de ritmo. Você chega descansado à prova.", "de": "Tapering: minimaler Umfang, einige Tempo-Erinnerungen. Du gehst frisch ins Rennen.", "nl": "Taperen: minimaal volume, een paar korte tempoherhalingen. Je komt fris aan de start van de wedstrijd.", "ja": "調整（テーパー）：ボリュームは最小、ペースの確認を少し。レースにはフレッシュな状態で臨みます。", "tr": "Yarış öncesi yük azaltma: minimum hacim, birkaç tempo hatırlatması. Yarışa taze geliyorsun."}}'::jsonb) WHERE name_key = 'triathlon_m_8w_name';
